import {createCircuitLayout} from './circuit-layout.mjs';
export function circuitBounds(layout){let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity,maxY=-Infinity;for(let i=0;i<512;i++){const p=layout.position(layout.length*i/512);minX=Math.min(minX,p[0]);maxX=Math.max(maxX,p[0]);minZ=Math.min(minZ,p[2]);maxZ=Math.max(maxZ,p[2]);maxY=Math.max(maxY,p[1]);}const pad=Math.max(55,Math.max(maxX-minX,maxZ-minZ)*.11);return {minX:minX-pad,maxX:maxX+pad,minZ:minZ-pad,maxZ:maxZ+pad,maxY};}
export function aerialCars(race){const layout=createCircuitLayout(race.difficulty,race.trackLength);return [{distance:race.distance,x:race.x,label:'TÚ',color:'#ffcc42',player:true},...race.rivals.map((car,i)=>({...car,label:car.model==='tesla-model-3'?'ALBERTO':'OCTAVIA '+(i+1),color:car.model==='tesla-model-3'?'#ffffff':'#36a1ff'}))].map(car=>{const f=layout.frame(car.distance),offset=car.x*race.settings.roadHalf;return {...car,point:[f.p[0]+f.r[0]*offset,f.p[1]+1,f.p[2]+f.r[2]*offset],angle:Math.atan2(f.t[0],-f.t[2])};});}
export function aerialProjection(bounds,width,height){const cx=(bounds.minX+bounds.maxX)/2,cz=(bounds.minZ+bounds.maxZ)/2;const scale=Math.min(width/(bounds.maxX-bounds.minX),height/(bounds.maxZ-bounds.minZ));return point=>[width/2+(point[0]-cx)*scale,height/2+(point[2]-cz)*scale];}
export function drawAerialFallback(ctx,race,width,height){const layout=createCircuitLayout(race.difficulty,race.trackLength),bounds=circuitBounds(layout),project=aerialProjection(bounds,width,height);ctx.fillStyle='#5e6854';ctx.fillRect(0,0,width,height);const scale=Math.min(width/(bounds.maxX-bounds.minX),height/(bounds.maxZ-bounds.minZ));for(const [extra,color] of [[5,'#b1a898'],[1.4,'#d5d3c8'],[0,'#393d3f']]){ctx.strokeStyle=color;ctx.lineWidth=Math.max(2,(race.settings.roadHalf*2+extra)*scale);ctx.lineJoin='round';ctx.beginPath();for(let i=0;i<=512;i++){const [x,y]=project(layout.position(layout.length*i/512));i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}return project;}
export function drawAerialCars(ctx,race,width,height,project){const cars=aerialCars(race);ctx.save();for(const [i,car] of cars.entries()){const [x,y]=project(car.point);ctx.translate(x,y);ctx.rotate(car.angle);ctx.fillStyle='#0009';ctx.fillRect(-4,-5,9,13);ctx.fillStyle=car.color;ctx.fillRect(-3,-6,6,12);ctx.fillStyle='#172534';ctx.fillRect(-2,-3,4,4);ctx.rotate(-car.angle);ctx.translate(-x,-y);const label=car.label,side=i%2?-1:1,lx=Math.max(44,Math.min(width-44,x+side*(36+(i>1?30:0)))),ly=Math.max(50,Math.min(height-42,y-25-i*15));ctx.strokeStyle=car.color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(lx,ly);ctx.stroke();ctx.font='bold 10px Arial';const tw=ctx.measureText(label).width;ctx.fillStyle='#101820e8';ctx.fillRect(lx-tw/2-5,ly-10,tw+10,16);ctx.fillStyle=car.color;ctx.textAlign='center';ctx.fillText(label,lx,ly+2);}ctx.restore();return cars;}
